import{_ as t,o as n,c as i,a3 as r}from"./chunks/framework.B9qR_F1m.js";const a="/bilder/anmeldung.jpg",b=JSON.parse('{"title":"Ablauf als Pilot","description":"","frontmatter":{},"headers":[],"relativePath":"ablaeufe/pilot.md","filePath":"ablaeufe/pilot.md"}'),s={name:"ablaeufe/pilot.md"};function l(d,e,o,h,g,u){return n(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="ablauf-als-pilot" tabindex="-1">Ablauf als Pilot <a class="header-anchor" href="#ablauf-als-pilot" aria-label="Permalink to &quot;Ablauf als Pilot&quot;">​</a></h1><p>Dein Mission Designer hat eine Mission in Shardwing geteilt und dir einen Link geschickt. Du brauchst nichts zu installieren – der Link öffnet sich im Browser. (Die <a href="/start/installieren">Desktop-App</a> geht genauso: dort <strong>Link öffnen</strong>, <kbd>⌘L</kbd> / <kbd>Strg+L</kbd>.)</p><h2 id="_1-·-platz-holen" tabindex="-1">1 · Platz holen <a class="header-anchor" href="#_1-·-platz-holen" aria-label="Permalink to &quot;1 · Platz holen&quot;">​</a></h2><p>Der Link führt zur <strong>Anmeldeseite</strong>: alle Flights der Mission mit ihren Plätzen – Flight Lead und Wingmen.</p><p><img src="'+a+'" alt="Anmeldeseite: ELI 1-1 und ROMAN 1-1 sind vergeben, ELI 1-2 ist gewählt" loading="lazy"></p><ol class="steps"><li>Freien Platz anklicken.</li><li>Namen oder Callsign eintragen.</li><li><b>„… übernehmen“</b> – du bekommst deinen <b>persönlichen Link</b>.</li></ol><div class="warning custom-block"><p class="custom-block-title">Persönlichen Link aufheben</p><p>Der Link ist auf diesem Gerät gespeichert. Leg trotzdem ein Lesezeichen an, um auf einem anderen Gerät weiterzuplanen. Verloren? Der Mission Designer kann ihn dir erneut geben.</p></div><h2 id="_2-·-was-du-siehst" tabindex="-1">2 · Was du siehst <a class="header-anchor" href="#_2-·-was-du-siehst" aria-label="Permalink to &quot;2 · Was du siehst&quot;">​</a></h2><p>Du siehst die Mission <strong>aus Sicht deines Flights</strong>: deine Route, die Bedrohungen, die für dich freigegeben sind, und die Unterlagen für alle. Was der Designer nicht freigegeben hat, siehst du nicht – das ist Absicht.</p><p>Oben steht der Sync-Status: <strong>Gespeichert</strong>, <strong>Speichert …</strong> oder <strong>Offline – Änderungen bleiben hier</strong>. Es gibt keinen Speichern-Knopf; alles geht automatisch an den Server, und Änderungen der anderen erscheinen live.</p><h2 id="_3-·-was-du-bearbeiten-darfst" tabindex="-1">3 · Was du bearbeiten darfst <a class="header-anchor" href="#_3-·-was-du-bearbeiten-darfst" aria-label="Permalink to &quot;3 · Was du bearbeiten darfst&quot;">​</a></h2><p>Das legt der Designer pro Flight fest. Üblich ist:</p><table tabindex="0"><thead><tr><th></th><th style="text-align:center;">Flight Lead</th><th style="text-align:center;">Wingman</th></tr></thead><tbody><tr><td>Route &amp; Steerpoints</td><td style="text-align:center;">✓</td><td style="text-align:center;"></td></tr><tr><td>Funk-Presets</td><td style="text-align:center;">✓</td><td style="text-align:center;"></td></tr><tr><td>CMDS</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td></tr><tr><td>Lineup Card</td><td style="text-align:center;">✓</td><td style="text-align:center;"></td></tr><tr><td>Eigene Threats</td><td style="text-align:center;">✓</td><td style="text-align:center;"></td></tr><tr><td>Beladung</td><td style="text-align:center;">✓</td><td style="text-align:center;"></td></tr></tbody></table><p>Wenn oben <strong>Nur lesen · Entwurf</strong> oder <strong>Nur lesen · Eingefroren</strong> steht, hat der Designer die Planung gerade gesperrt. (<a href="/gemeinsam/rollen#phasen">Phasen</a>)</p><h2 id="_4-·-typische-aufgaben" tabindex="-1">4 · Typische Aufgaben <a class="header-anchor" href="#_4-·-typische-aufgaben" aria-label="Permalink to &quot;4 · Typische Aufgaben&quot;">​</a></h2><p><strong>Als Flight Lead:</strong></p><ol><li>Route prüfen und anpassen – im Reiter <a href="/bereiche/flights#route">Route</a> oder im <a href="/bereiche/dtc">DTC</a>.</li><li><a href="/bereiche/beladung">Beladung</a> wählen, im Rahmen dessen, was der Designer erlaubt.</li><li><a href="/bereiche/lineup-card">Lineup Card</a>: Joker, Bingo, Hinweise für dein Element.</li><li><a href="/bereiche/angriff">Angriff</a> planen, wenn ihr ein Bodenziel habt.</li></ol><p><strong>Als Wingman (und Lead):</strong></p><ul><li><strong>Eigene CMDS-Programme und Farben</strong> – sie gelten nur für dein Flugzeug. Shardwing legt dafür eine persönliche Kopie der Cartridge an; deine Kameraden behalten ihre.</li><li><strong>Notizen</strong> zum eigenen Platz.</li></ul><h2 id="_5-·-einreichungen" tabindex="-1">5 · Einreichungen <a class="header-anchor" href="#_5-·-einreichungen" aria-label="Permalink to &quot;5 · Einreichungen&quot;">​</a></h2><p>Je nach Einstellung gehen Änderungen sofort in die Mission oder als <strong>Einreichung</strong> an den Designer. Er nimmt sie an oder lehnt sie mit Kommentar ab. Den Stand siehst du unter <strong>Einreichungen meines Flights</strong> in der Übersicht.</p><h2 id="_6-·-fliegen" tabindex="-1">6 · Fliegen <a class="header-anchor" href="#_6-·-fliegen" aria-label="Permalink to &quot;6 · Fliegen&quot;">​</a></h2><p>Der Designer speichert die fertige Mission und bringt sie auf den DCS-Server. Im Jet:</p><ul><li>Cartridge auf der <strong>DTE-Seite</strong> laden (oder sie lädt automatisch, wenn AutoLoad an ist).</li><li>Kneeboard mit <kbd>K</kbd> öffnen: Lineup Card, Comm Card, Routenkarte, Attack Card.</li></ul><p>Für unterwegs: In der <a href="/bereiche/uebersicht">Übersicht</a> gibt es für deinen Flight <strong>PDF</strong> und <strong>Kneeboard-ZIP</strong> zum Herunterladen.</p><p>Mehr dazu: <a href="/dcs/cockpit">Im Cockpit</a>. Alles zum Abhaken: <a href="./checklisten#flight-lead">Checklisten</a>.</p>',26)])])}const p=t(s,[["render",l]]);export{b as __pageData,p as default};
